class Codec {
    void encode(Node* node, std::ostringstream& out) {
        out << node->val << ' ' << node->children.size() << ' ';
        for (Node* child : node->children) {
            encode(child, out);
        }
    }

    Node* decode(std::istringstream& in) {
        int value, count;
        if (!(in >> value >> count)) {
            return nullptr;
        }
        Node* node = new Node(value);
        for (int i = 0; i < count; ++i) {
            node->children.push_back(decode(in));
        }
        return node;
    }

public:
    string serialize(Node* root) {
        if (!root) {
            return "";
        }
        std::ostringstream out;
        encode(root, out);
        return out.str();
    }

    Node* deserialize(string data) {
        if (data.empty()) {
            return nullptr;
        }
        std::istringstream in(data);
        return decode(in);
    }
};
